parameters.jsCode:
// Preparação do Contexto para a LLM (Autenticação realizada via Basic Auth nativo no Webhook)
const body = $input.item.json.body || $input.item.json;
const userMessage = body.query?.message || 'Olá';
const userName = body.user?.name || 'Usuário';
const financialContextStr = JSON.stringify(body.financialContext || {}, null, 2);
const systemDocStr = body.systemDocumentation || '';

return [{
  json: {
    valid: true,
    requestId: body.requestId,
    conversationId: body.conversationId,
    userName,
    userMessage,
    prompt: `Contexto Financeiro do Usuário (${userName}):\n${financialContextStr}\n\nDocumentação do Sistema OmniFin:\n${systemDocStr}\n\nPergunta do Usuário:\n${userMessage}`
  }
}];

parameters.responseBody:
={
  "success": true,
  "conversationId": $json.conversationId,
  "answer": $json.answer || "Olá! Sou o Assistente OmniFin. Como posso te ajudar hoje?",
  "suggestions": [
    "Resumo das despesas do mês",
    "Quais categorias estão perto do teto?",
    "Como funciona a Simulação?"
  ]
}
